databaseInitialization:
-- This master script fully synchronizes the database schema.
-- It is idempotent, meaning it is safe to run multiple times, and non-destructive.

-- =========
-- SECTION 0: CLEANUP
-- =========
DROP TRIGGER IF EXISTS subject_teacher_sync_trigger ON public.subjects;
DROP TRIGGER IF EXISTS subject_enrollments_set_teacher_trg ON public.subject_enrollments;
DROP FUNCTION IF EXISTS public.sync_subject_teacher_to_enrollments();
DROP FUNCTION IF EXISTS public.subject_enrollments_set_teacher();

-- =========
-- SECTION 1: CUSTOM TYPES
-- =========
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'user_role') THEN
        CREATE TYPE public.user_role AS ENUM ('Student', 'Teacher', 'Admin');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'card_color') THEN
        CREATE TYPE public.card_color AS ENUM ('pink', 'red', 'orange', 'yellow', 'green', 'blue', 'purple', 'gray');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'game_mode') THEN
        CREATE TYPE public.game_mode AS ENUM ('CLASSIC', 'QUIZ');
    END IF;
END;
$$;

-- =========
-- SECTION 2: PROFILES TABLE
-- =========
CREATE TABLE IF NOT EXISTS public.profiles (
    id UUID PRIMARY KEY NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    full_name TEXT,
    role public.user_role NOT NULL DEFAULT 'Student',
    course TEXT
);
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow users to view their own profile" ON public.profiles;
CREATE POLICY "Allow users to view their own profile" ON public.profiles FOR SELECT USING (auth.uid() = id);
DROP POLICY IF EXISTS "Allow users to update their own profile" ON public.profiles;
CREATE POLICY "Allow users to update their own profile" ON public.profiles FOR UPDATE USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
DROP POLICY IF EXISTS "Allow users to insert their own profile" ON public.profiles;
CREATE POLICY "Allow users to insert their own profile" ON public.profiles FOR INSERT WITH CHECK (auth.uid() = id);
DROP POLICY IF EXISTS "Allow authenticated users to view other profiles" ON public.profiles;
CREATE POLICY "Allow authenticated users to view other profiles" ON public.profiles FOR SELECT USING (auth.role() = 'authenticated');

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO public.profiles (id, full_name, role, course)
    VALUES (
        new.id,
        new.raw_user_meta_data ->> 'full_name',
        (COALESCE(new.raw_user_meta_data ->> 'role', 'Student'))::public.user_role,
        new.raw_user_meta_data ->> 'course'
    );
    RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- =========
-- SECTION 3: DECKS & FLASHCARDS TABLES
-- =========
CREATE TABLE IF NOT EXISTS public.decks (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    color public.card_color NOT NULL,
    mode public.game_mode NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.decks ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Students can view assigned decks" ON public.decks;
CREATE POLICY "Students can view assigned decks" ON public.decks FOR SELECT
USING (
    EXISTS (
        SELECT 1 FROM public.subject_decks sd
        JOIN public.subject_enrollments se ON sd.subject_id = se.subject_id
        WHERE sd.deck_id = public.decks.id AND se.student_id = auth.uid() AND se.status = 'approved'
    )
);
DROP POLICY IF EXISTS "Owners can manage their own decks" ON public.decks;
CREATE POLICY "Owners can manage their own decks" ON public.decks FOR ALL
USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

CREATE TABLE IF NOT EXISTS public.flashcards (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    deck_id BIGINT NOT NULL,
    question TEXT NOT NULL,
    answer TEXT,
    options JSONB,
    correct_answer TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'flashcards_deck_id_fkey' AND conrelid = 'public.flashcards'::regclass) THEN
        ALTER TABLE public.flashcards ADD CONSTRAINT flashcards_deck_id_fkey FOREIGN KEY (deck_id) REFERENCES public.decks(id) ON DELETE CASCADE;
    END IF;
END;
$$;
ALTER TABLE public.flashcards ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users can view flashcards in their decks or assigned decks" ON public.flashcards;
CREATE POLICY "Users can view flashcards in their decks or assigned decks" ON public.flashcards FOR SELECT
USING (
    (auth.uid() = (SELECT user_id FROM public.decks WHERE id = deck_id))
    OR
    EXISTS (
        SELECT 1 FROM public.subject_decks sd
        JOIN public.subject_enrollments se ON sd.subject_id = se.subject_id
        WHERE sd.deck_id = public.flashcards.deck_id AND se.student_id = auth.uid() AND se.status = 'approved'
    )
);
DROP POLICY IF EXISTS "Users can manage flashcards in their own decks" ON public.flashcards;
CREATE POLICY "Users can manage flashcards in their own decks" ON public.flashcards FOR ALL
USING (auth.uid() = (SELECT user_id FROM public.decks WHERE id = deck_id))
WITH CHECK (auth.uid() = (SELECT user_id FROM public.decks WHERE id = deck_id));

-- =========
-- SECTION 4: SUBJECTS TABLE
-- =========
CREATE OR REPLACE FUNCTION public.generate_subject_code()
RETURNS TEXT AS $$
BEGIN
    RETURN (SELECT string_agg(c, '') FROM (SELECT c FROM unnest(string_to_array('ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', NULL)) c ORDER BY random() LIMIT 8) AS sub);
END;
$$ LANGUAGE plpgsql;

CREATE TABLE IF NOT EXISTS public.subjects (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    teacher_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    description TEXT,
    image_url TEXT,
    subject_code TEXT UNIQUE NOT NULL DEFAULT public.generate_subject_code(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.subjects ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Teachers can manage their own subjects" ON public.subjects;
CREATE POLICY "Teachers can manage their own subjects" ON public.subjects FOR ALL
USING (auth.uid() = teacher_id) WITH CHECK (auth.uid() = teacher_id);
DROP POLICY IF EXISTS "Authenticated users can view all subjects" ON public.subjects;
CREATE POLICY "Authenticated users can view all subjects" ON public.subjects FOR SELECT USING (auth.role() = 'authenticated');

-- =========
-- SECTION 5: ENROLLMENTS & SUBJECT DECKS
-- =========
CREATE TABLE IF NOT EXISTS public.subject_enrollments (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    subject_id BIGINT NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE,
    student_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved')),
    enrolled_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.subject_enrollments ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Students can manage their own enrollments" ON public.subject_enrollments;
CREATE POLICY "Students can manage their own enrollments" ON public.subject_enrollments FOR ALL
USING (auth.uid() = student_id) WITH CHECK (auth.uid() = student_id);
DROP POLICY IF EXISTS "Teachers can manage enrollments for their subjects" ON public.subject_enrollments;
CREATE POLICY "Teachers can manage enrollments for their subjects" ON public.subject_enrollments FOR ALL
USING ((SELECT teacher_id FROM public.subjects WHERE id = subject_id) = auth.uid());

CREATE TABLE IF NOT EXISTS public.subject_decks (
    subject_id BIGINT NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE,
    deck_id BIGINT NOT NULL REFERENCES public.decks(id) ON DELETE CASCADE,
    added_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (subject_id, deck_id)
);
ALTER TABLE public.subject_decks ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Teachers can manage deck assignments" ON public.subject_decks;
CREATE POLICY "Teachers can manage deck assignments" ON public.subject_decks FOR ALL
USING ((SELECT teacher_id FROM public.subjects WHERE id = subject_id) = auth.uid());
DROP POLICY IF EXISTS "Enrolled students can view assigned decks" ON public.subject_decks;
CREATE POLICY "Enrolled students can view assigned decks" ON public.subject_decks FOR SELECT
USING (EXISTS (SELECT 1 FROM public.subject_enrollments se WHERE se.subject_id = public.subject_decks.subject_id AND se.student_id = auth.uid() AND se.status = 'approved'));

-- =========
-- SECTION 6: STUDY SESSIONS TABLE
-- =========
CREATE TABLE IF NOT EXISTS public.study_sessions (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    deck_id BIGINT NOT NULL REFERENCES public.decks(id) ON DELETE CASCADE,
    score_percentage SMALLINT NOT NULL CHECK (score_percentage >= 0 AND score_percentage <= 100),
    correct_count INT NOT NULL,
    total_cards INT NOT NULL,
    completed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.study_sessions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users can manage their own study sessions" ON public.study_sessions;
CREATE POLICY "Users can manage their own study sessions" ON public.study_sessions FOR ALL
USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

-- =========
-- SECTION 7: FRIENDSHIPS TABLE
-- =========
CREATE TABLE IF NOT EXISTS public.friendships (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    user1_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    user2_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    requester_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT friendships_unique_pair UNIQUE (user1_id, user2_id),
    CONSTRAINT check_users_not_same CHECK (user1_id <> user2_id),
    CONSTRAINT check_users_ordered CHECK (user1_id < user2_id)
);
ALTER TABLE public.friendships ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users can manage their own friendships" ON public.friendships;
CREATE POLICY "Users can manage their own friendships" ON public.friendships FOR ALL
USING (auth.uid() = user1_id OR auth.uid() = user2_id);

-- =========
-- SECTION 8: RPC FUNCTIONS
-- =========
CREATE OR REPLACE FUNCTION public.get_admin_stats()
RETURNS TABLE(total_users BIGINT, student_users BIGINT, teacher_users BIGINT, total_subjects BIGINT) AS $$
BEGIN
    RETURN QUERY
    SELECT
        (SELECT count(*) FROM auth.users) AS total_users,
        (SELECT count(*) FROM public.profiles WHERE role = 'Student') AS student_users,
        (SELECT count(*) FROM public.profiles WHERE role = 'Teacher') AS teacher_users,
        (SELECT count(*) FROM public.subjects) AS total_subjects;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.search_decks(search_term TEXT)
RETURNS SETOF public.decks AS $$
BEGIN
    RETURN QUERY
    SELECT * FROM public.decks
    WHERE title ILIKE '%' || search_term || '%';
END;
$$ LANGUAGE plpgsql STABLE SECURITY INVOKER;

CREATE OR REPLACE FUNCTION public.delete_deck(deck_id_to_delete BIGINT)
RETURNS VOID AS $$
BEGIN
    DELETE FROM public.decks WHERE id = deck_id_to_delete AND user_id = auth.uid();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.delete_subject(subject_id_to_delete BIGINT)
RETURNS VOID AS $$
BEGIN
    DELETE FROM public.subjects WHERE id = subject_id_to_delete AND teacher_id = auth.uid();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.enroll_in_subject(subject_code_to_enroll TEXT)
RETURNS table(success boolean, message text) AS $$
DECLARE
    target_subject_id BIGINT;
    is_already_enrolled BOOLEAN;
BEGIN
    SELECT id INTO target_subject_id FROM public.subjects WHERE subject_code = subject_code_to_enroll;
    IF target_subject_id IS NULL THEN
        RETURN QUERY SELECT false, 'Invalid subject code.';
        RETURN;
    END IF;
    SELECT EXISTS (SELECT 1 FROM public.subject_enrollments WHERE subject_id = target_subject_id AND student_id = auth.uid()) INTO is_already_enrolled;
    IF is_already_enrolled THEN
        RETURN QUERY SELECT false, 'You are already enrolled or have a pending request for this subject.';
        RETURN;
    END IF;
    INSERT INTO public.subject_enrollments (subject_id, student_id, status) VALUES (target_subject_id, auth.uid(), 'pending');
    RETURN QUERY SELECT true, 'Enrollment request sent successfully!';
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.unenroll_from_subject(subject_id_to_unenroll BIGINT)
RETURNS VOID AS $$
BEGIN
    DELETE FROM public.subject_enrollments WHERE subject_id = subject_id_to_unenroll AND student_id = auth.uid();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.get_friends_and_requests()
RETURNS JSON AS $$
DECLARE
    friends_list JSON;
    requests_list JSON;
BEGIN
    SELECT json_agg(f) INTO friends_list FROM (
        SELECT fs.id as friendship_id, p.id as user_id, p.full_name, p.course
        FROM friendships fs
        JOIN profiles p ON p.id = CASE WHEN fs.user1_id = auth.uid() THEN fs.user2_id ELSE fs.user1_id END
        WHERE (fs.user1_id = auth.uid() OR fs.user2_id = auth.uid()) AND fs.status = 'accepted'
    ) f;
    SELECT json_agg(r) INTO requests_list FROM (
        SELECT fs.id as friendship_id, fs.requester_id, p.full_name, p.course
        FROM friendships fs
        JOIN profiles p ON p.id = fs.requester_id
        WHERE (fs.user2_id = auth.uid()) AND fs.status = 'pending'
    ) r;
    RETURN json_build_object('friends', COALESCE(friends_list, '[]'), 'requests', COALESCE(requests_list, '[]'));
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.search_students(search_term TEXT)
RETURNS TABLE(id UUID, full_name TEXT, course TEXT) AS $$
BEGIN
    RETURN QUERY
    SELECT p.id, p.full_name, p.course FROM public.profiles p
    WHERE p.id <> auth.uid() AND p.full_name ILIKE '%' || search_term || '%'
    AND NOT EXISTS (
        SELECT 1 FROM public.friendships fs
        WHERE (fs.user1_id = auth.uid() AND fs.user2_id = p.id) OR (fs.user1_id = p.id AND fs.user2_id = auth.uid())
    )
    LIMIT 10;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- =========
-- SECTION 9: CO-OP LOBBIES
-- =========
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'lobby_status') THEN
        CREATE TYPE public.lobby_status AS ENUM ('waiting', 'in_progress', 'finished');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'lobby_member_status') THEN
        CREATE TYPE public.lobby_member_status AS ENUM ('invited', 'joined', 'left');
    END IF;
END;
$$;

CREATE TABLE IF NOT EXISTS public.lobbies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    host_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    status public.lobby_status NOT NULL DEFAULT 'waiting',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deck_id BIGINT REFERENCES public.decks(id) ON DELETE SET NULL
);
ALTER TABLE public.lobbies ENABLE ROW LEVEL SECURITY;
-- Allow realtime on lobbies table
ALTER PUBLICATION supabase_realtime ADD TABLE public.lobbies;


CREATE TABLE IF NOT EXISTS public.lobby_members (
    lobby_id UUID NOT NULL REFERENCES public.lobbies(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    status public.lobby_member_status NOT NULL DEFAULT 'invited',
    score INT NOT NULL DEFAULT 0,
    joined_at TIMESTAMPTZ,
    PRIMARY KEY (lobby_id, user_id)
);
ALTER TABLE public.lobby_members ENABLE ROW LEVEL SECURITY;
-- Allow realtime on lobby_members table
ALTER PUBLICATION supabase_realtime ADD TABLE public.lobby_members;

-- Policies for Lobbies
DROP POLICY IF EXISTS "Users can see lobbies they are a member of" ON public.lobbies;
CREATE POLICY "Users can see lobbies they are a member of" ON public.lobbies FOR SELECT
USING (EXISTS (SELECT 1 FROM public.lobby_members WHERE lobby_id = id AND user_id = auth.uid()));

DROP POLICY IF EXISTS "Hosts can create and manage their own lobbies" ON public.lobbies;
CREATE POLICY "Hosts can create and manage their own lobbies" ON public.lobbies FOR ALL
USING (auth.uid() = host_id) WITH CHECK (auth.uid() = host_id);

-- Policies for Lobby Members
DROP POLICY IF EXISTS "Users can see members of lobbies they are in" ON public.lobby_members;
CREATE POLICY "Users can see members of lobbies they are in" ON public.lobby_members FOR SELECT
USING (EXISTS (SELECT 1 FROM public.lobbies l JOIN public.lobby_members lm ON l.id = lm.lobby_id WHERE l.id = public.lobby_members.lobby_id AND lm.user_id = auth.uid()));

DROP POLICY IF EXISTS "Users can join or leave lobbies they are invited to" ON public.lobby_members;
CREATE POLICY "Users can join or leave lobbies they are invited to" ON public.lobby_members FOR UPDATE
USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

DROP POLICY IF EXISTS "Hosts can add/remove members from their lobbies" ON public.lobby_members;
CREATE POLICY "Hosts can add/remove members from their lobbies" ON public.lobby_members FOR ALL
USING ((SELECT host_id FROM public.lobbies WHERE id = lobby_id) = auth.uid());

DROP POLICY IF EXISTS "Users can see their own lobby member entry" ON public.lobby_members;
CREATE POLICY "Users can see their own lobby member entry" ON public.lobby_members FOR SELECT
USING (user_id = auth.uid());


-- RPC to create a lobby and invite the first friend
CREATE OR REPLACE FUNCTION public.create_lobby_and_invite(invitee_id UUID)
RETURNS TABLE(id UUID, host_id UUID, status public.lobby_status, created_at TIMESTAMPTZ, deck_id BIGINT) AS $$
DECLARE
    new_lobby_id UUID;
    new_lobby public.lobbies;
BEGIN
    -- Create the new lobby
    INSERT INTO public.lobbies (host_id) VALUES (auth.uid()) RETURNING * INTO new_lobby;
    new_lobby_id := new_lobby.id;

    -- Add the host as a member with 'joined' status
    INSERT INTO public.lobby_members (lobby_id, user_id, status, joined_at)
    VALUES (new_lobby_id, auth.uid(), 'joined', NOW());

    -- Invite the friend with 'invited' status
    INSERT INTO public.lobby_members (lobby_id, user_id, status)
    VALUES (new_lobby_id, invitee_id, 'invited');

    RETURN QUERY SELECT * FROM public.lobbies WHERE public.lobbies.id = new_lobby_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
